#include <bits/stdc++.h>
using namespace std;

// Retorna a soma dos elementos no intervalo [firstIndex, lastIndex).
long long sumRange(const vector<long long>& values, int firstIndex, int lastIndex) {
    long long rangeSum = 0;
    for (int currentIndex = firstIndex; currentIndex < lastIndex; ++currentIndex) {
        rangeSum += values[currentIndex];
    }
    return rangeSum;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int valueCount;
    cin >> valueCount;
    vector<long long> values(valueCount);
    for (long long& value : values) cin >> value;
    cout << sumRange(values, 0, valueCount) << "\n";
}

