// A profundidade é logarítmica porque o intervalo é dividido ao meio.
int binarySearch(const vector<int>& sortedValues, int targetValue) {
    int leftIndex = 0, rightIndex = (int)sortedValues.size() - 1;
    while (leftIndex <= rightIndex) {
        int middleIndex = leftIndex + (rightIndex - leftIndex) / 2;
        if (sortedValues[middleIndex] == targetValue) return middleIndex;
        if (sortedValues[middleIndex] < targetValue) leftIndex = middleIndex + 1;
        else rightIndex = middleIndex - 1;
    }
    return -1;
}
